import AppKit

public final class BrandAssets: Sendable {
    public static let shared = BrandAssets()
    
    public static let colorIconBase64 = ""
    public static let templateIconBase64 = ""
    
    // MARK: - New Status Bar SVGs (On.svg & off.svg)
    public static let menuBarOnSvgBase64 = ""
    public static let menuBarOnLightSvgBase64 = ""
    public static let menuBarOffSvgBase64 = ""
    
    private init() {}
    
    public static var appIconImage: NSImage {
        if let data = Data(base64Encoded: colorIconBase64),
           let img = NSImage(data: data) {
            return img
        }
        return NSApp.applicationIconImage
    }
    
    public static var templateIconImage: NSImage {
        if let data = Data(base64Encoded: templateIconBase64),
           let img = NSImage(data: data) {
            img.isTemplate = true
            return img
        }
        return NSImage(systemSymbolName: "pencil.and.list.clipboard", accessibilityDescription: "SFinder") ?? NSImage()
    }
    
    public static func toolbarIcon(size: NSSize = NSSize(width: 18, height: 18)) -> NSImage {
        if let data = Data(base64Encoded: templateIconBase64),
           let img = NSImage(data: data) {
            let resized = NSImage(size: size, flipped: false) { rect in
                img.draw(in: rect)
                return true
            }
            resized.isTemplate = true
            return resized
        }
        return NSImage(systemSymbolName: "pencil.and.list.clipboard", accessibilityDescription: "SFinder") ?? NSImage()
    }
    
    // MARK: - Status Bar Icons (On.svg & off.svg)
    
    private static func loadSvg(base64: String, resourceName: String) -> NSImage? {
        // 1. Try bundle resource
        if let url = Bundle.main.url(forResource: resourceName, withExtension: "svg"),
           let img = NSImage(contentsOf: url) {
            return img
        }
        // 2. Base64 fallback
        if let data = Data(base64Encoded: base64),
           let img = NSImage(data: data) {
            return img
        }
        return nil
    }
    
    public static func menuBarIcon(isActive: Bool = false) -> NSImage {
        if isActive {
            return wakeActiveIcon()
        } else {
            return wakeInactiveIcon()
        }
    }
    
    /// Biểu tượng trạng thái giữ thức ĐANG BẬT (Active — On.svg with glowing lime green center)
    public static func wakeActiveIcon(size: NSSize = NSSize(width: 18, height: 18)) -> NSImage {
        let img = NSImage(size: size, flipped: false) { rect in
            let appearance = NSAppearance.currentDrawing()
            let isDark = appearance.bestMatch(from: [.darkAqua, .aqua]) == .darkAqua
            let b64 = isDark ? menuBarOnSvgBase64 : menuBarOnLightSvgBase64
            let resName = isDark ? "MenuBarOn" : "MenuBarOnLight"
            if let svg = loadSvg(base64: b64, resourceName: resName) {
                svg.draw(in: rect, from: .zero, operation: .sourceOver, fraction: 1.0)
                return true
            }
            return false
        }
        img.isTemplate = false
        return img
    }
    
    /// Biểu tượng trạng thái nghỉ (Inactive — off.svg in Template mode)
    public static func wakeInactiveIcon(size: NSSize = NSSize(width: 18, height: 18)) -> NSImage {
        if let svg = loadSvg(base64: menuBarOffSvgBase64, resourceName: "MenuBarOff") {
            svg.size = size
            svg.isTemplate = true
            return svg
        }
        let img = NSImage(size: size, flipped: false) { rect in
            if let svg = loadSvg(base64: menuBarOffSvgBase64, resourceName: "MenuBarOff") {
                svg.draw(in: rect, from: .zero, operation: .sourceOver, fraction: 1.0)
                return true
            }
            return false
        }
        img.isTemplate = true
        return img
    }
    
    public static func whiteMenuIcon(size: NSSize = NSSize(width: 16, height: 16)) -> NSImage {
        if let data = Data(base64Encoded: templateIconBase64),
           let img = NSImage(data: data) {
            let whiteImg = NSImage(size: size, flipped: false) { rect in
                NSGraphicsContext.saveGraphicsState()
                img.draw(in: rect)
                NSColor.white.set()
                rect.fill(using: .sourceAtop)
                NSGraphicsContext.restoreGraphicsState()
                return true
            }
            whiteImg.isTemplate = false
            return whiteImg
        }
        return NSImage()
    }
}
